// The TypeScript engine must reproduce Riley's workbook cell for cell.
//
// reference_cases.json = 20 LibreOffice recalculations of Heat_Pump_Calculator.xlsx, 45 cells each
// (generated by hp_engine/scripts/make_reference_cases.py; the Python engine passes the same file).
// Run:  npm test        (node --experimental-strip-types --test tests/)
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import { DEFAULT_ASSUMPTIONS, runEngine, withOverrides, type EngineData, type EngineResult,
  type HouseInputs } from "../lib/engine/index.ts";

const here = path.dirname(fileURLToPath(import.meta.url));
const DATA: EngineData = JSON.parse(fs.readFileSync(path.join(here, "../data/engine/indiana-engine-data.json"), "utf8"));
const REF = JSON.parse(fs.readFileSync(path.join(here, "reference_cases.json"), "utf8")).cases as
  Record<string, { inputs: Partial<HouseInputs>; cells: Record<string, number | string> }>;

const CELL: Record<string, (r: EngineResult) => number | string> = {
  "House!F5": (r) => r.house.floorArea,
  "House!F6": (r) => r.house.stories,
  "House!F7": (r) => r.house.bedrooms,
  "House!F40": (r) => r.house.ua,
  "House!F42": (r) => r.house.envelope.ach50,
  "House!F44": (r) => r.house.elaIn2,
  "House!F45": (r) => r.house.stackCoeff,
  "House!F46": (r) => r.house.windCoeff,
  "House!F52": (r) => r.house.internalGainBtuh,
  "Weather!B11": (r) => r.weather.hdd65,
  "Weather!B12": (r) => r.weather.hdd65Rebuilt,
  "Weather!B13": (r) => r.weather.cdd65Rebuilt,
  "Weather!B15": (r) => r.weather.totalHours,
  "Loads!B6": (r) => r.loads.heatAnnualMmbtu,
  "Loads!B7": (r) => r.loads.coolAnnualMmbtu,
  "Loads!B8": (r) => r.loads.latentAnnualMmbtu,
  "Loads!B9": (r) => r.loads.heatingHours,
  "Loads!B10": (r) => r.loads.coolingHours,
  "Loads!B14": (r) => r.loads.designHeatBtuh,
  "Loads!B17": (r) => r.loads.designCoolBtuh,
  "Loads!B34": (r) => r.loads.sunHeatBtuh,
  "Loads!B35": (r) => r.loads.sunCoolBtuh,
  "Loads!B36": (r) => r.loads.indoorHumidity,
  "Loads!B37": (r) => r.loads.ventilationCfm,
  "HP Rating!D35": (r) => r.hpRating.resistanceShare,
  "HP Rating!D37": (r) => r.hpRating.compressorBtuPerWh,
  "Equipment!D33": (r) => r.equipment.hpSizeBtuh,
  "Equipment!D39": (r) => r.equipment.hpCapAtDesign,
  "Equipment!D40": (r) => r.equipment.designCoverage,
  "Equipment!D42": (r) => r.equipment.fanKwh,
  "Equipment!B46": (r) => r.equipment.gasFurnace.therms,
  "Equipment!C46": (r) => r.equipment.gasFurnace.kwh,
  "Equipment!B47": (r) => r.equipment.propaneFurnace.gallons,
  "Equipment!C48": (r) => r.equipment.electricFurnaceKwh,
  "Equipment!C49": (r) => r.equipment.heatPumpKwh,
  "Equipment!C50": (r) => r.equipment.backupKwh,
  "Equipment!C51": (r) => r.equipment.backupHeatShare,
  "Results!G17": (r) => r.results.systems["Gas furnace + AC"].totalMmbtu,
  "Results!G18": (r) => r.results.systems["Propane furnace + AC"].totalMmbtu,
  "Results!G19": (r) => r.results.systems["Electric furnace + AC"].totalMmbtu,
  "Results!G20": (r) => r.results.systems["Standard heat pump"].totalMmbtu,
  "Results!B9": (r) => r.results.change.total,
  "Results!B10": (r) => r.results.change.heating,
  "Results!B11": (r) => r.results.change.cooling,
};
const SKIP = new Set(["Results!B12"]); // the ready-made site-energy sentence is intentionally not produced

const close = (a: number, b: number) => Math.abs(a - b) <= 1e-9 * Math.max(1, Math.abs(b));

for (const [name, ref] of Object.entries(REF)) {
  test(`workbook parity: ${name}`, () => {
    const r = runEngine(DATA, ref.inputs);
    const bad: string[] = [];
    for (const [cell, want] of Object.entries(ref.cells)) {
      if (SKIP.has(cell)) continue;
      const read = CELL[cell];
      assert.ok(read, `no mapping for ${cell}`);
      const got = read(r);
      if (typeof want === "number" ? !close(got as number, want) : got !== want) {
        bad.push(`${cell}: workbook ${want}, engine ${got}`);
      }
    }
    assert.deepEqual(bad, []);
  });
}

test("default house matches the workbook's cached values", () => {
  const e = runEngine(DATA).equipment;
  assert.ok(close(e.gasFurnace.therms, 886.236108539174));
  assert.ok(close(e.heatPumpKwh, 11306.8102340663));
  assert.equal(e.hpSizeBtuh, 36000);
});

test("all 92 counties run and each weather year sums to 8,760 hours", () => {
  assert.equal(Object.keys(DATA.counties).length, 92);
  for (const county of Object.keys(DATA.counties)) {
    for (const weather_year of ["Average", "Mild", "Extreme"] as const) {
      const r = runEngine(DATA, { county, weather_year });
      assert.ok(Math.abs(r.weather.totalHours - 8760) < 1, county);
      assert.ok(r.equipment.heatPumpKwh > 0, county);
    }
  }
});

test("red-team sensitivities reproduce (sizing and shading)", () => {
  const at = (changes: Parameters<typeof withOverrides>[0]) => runEngine(DATA, {}, withOverrides(changes)).equipment;
  assert.equal(at({ sizing: { sizeFactor: 1.15 } }).hpSizeBtuh, 30000);
  assert.ok(Math.abs(at({ sizing: { sizeFactor: 1.15 } }).backupHeatShare - 0.166) < 0.001);
  assert.ok(Math.abs(at({ sizing: { sizeFactor: 1.0 } }).backupHeatShare - 0.242) < 0.001);
  assert.ok(Math.abs(at({ sun: { exteriorShading: 0.7 } }).backupHeatShare - 0.176) < 0.001);
  assert.equal(DEFAULT_ASSUMPTIONS.sizing.sizeFactor, 1.25); // overrides never mutate the defaults
  assert.throws(() => withOverrides({ sun: { nope: 1 } as never }));
});
